const data={
  services:[['Research & Strategy Advisory','Evidence-led market research, sector studies and strategy that reposition businesses for growth.',['MARKET RESEARCH','SECTOR STUDIES','GO-TO-MARKET','COMPETITIVE INTEL']],['Data-driven Insights','Survey infrastructure and data tools that give investors and operators a real market edge.',['SURVEY INFRASTRUCTURE','DASHBOARDS','DATA PIPELINES']],['Business Transformation & AI','Operating-model redesign and applied AI that turn digital potential into measurable performance.',['OPERATING MODELS','APPLIED AI','AUTOMATION','CHANGE MGMT']],['Startups & SME Support','Hands-on support that helps young, creative ventures scale and attract investment.',['INVESTMENT READINESS','MARKET ENTRY','GROWTH STRATEGY']],['Partnerships & Events','We identify growth opportunities in partnership and key industry events.',['CONFERENCES','ROUNDTABLES','PARTNERSHIPS']],['Tailored Solutions','We are always open to discuss ideas and issues that need keen eyes and experienced hands.',['BESPOKE ADVISORY']]],
  insights:[['Running on empty: the perpetual struggle with petrol scarcity in Nigeria','qu.png'],['COVID-19: vaccine gap, hesitancy, and wastage','vaccine.png'],['The implication of the African Sustainability Index for the Nigerian health sector II – Financing','health.jpg']],
  team:[['Uju Ikedionu-Obichukwu, MSc','Fintech & Data Insight','uju.jpg'],['Idris Shonubi, MSc','Agritech & Data Insight','idris.jpg'],['Olawale Kasali, PhD','Modelling & Advancement','kasali.jpg'],['Ikechukwu Okafor, MSc','Energytech & Finance','ike.png'],['Amam Okafor, MSc','Digital Economy','amam.jpeg'],['Chukwuma Dim, PhD','Finance And Big Data','chukwuma.jpg'],['Gideon Ndubuisi, PhD','Green Industrialization & Structural Change','gideon.jpeg']]
};
const A='/assets/';
function header(){return `<header class="header"><div class="wrap nav"><a href="/"><img class="logo" src="${A}logo.png" alt="Native Insight"></a><nav class="navlinks"><a href="/about/">About</a><a href="/what-we-do/">What We Do</a><a href="/insights/">Insights</a><a href="/media/">Media</a><a href="/careers/">Careers</a></nav><a class="btn" href="/contact/">Tell us your challenge →</a><button class="menu" aria-label="Open menu">☰</button></div></header><div class="mobile-panel">${['About','What We Do','Insights','Reports','Team','Media','Careers','Events','Academy','Contact'].map(x=>`<a href="/${x.toLowerCase().replaceAll(' ','-').replace('team','our-team').replace('events','ni-events')}/">${x}</a>`).join('')}</div>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footgrid"><div><img class="logo" src="${A}logo-white.png" alt="Native Insight"><p class="tagline">Local solution.<br>Pan-African perspective.<br>Global participation.</p></div><div><h4>COMPANY</h4><a href="/about/">About Us</a><a href="/our-team/">Our Team</a><a href="/careers/">Careers</a><a href="/contact/">Contact</a></div><div><h4>WHAT WE DO</h4><a href="/what-we-do/">Research & Strategy</a><a href="/what-we-do/">Business Transformation & AI</a><a href="/what-we-do/">Data-driven Insights</a></div><div><h4>ENGAGE</h4><a href="/insights/">Insights</a><a href="/reports/">Reports</a><a href="/ni-events/">Events</a><a href="/academy/">Academy</a><a href="/media/">Media</a></div></div><div class="copyright">Native Insight © 2026 · Lagos · Abuja · Nairobi · Accra</div></div></footer>`}
const serviceRows=()=>`<div class="services">${data.services.map((s,i)=>`<article class="service reveal"><span class="num">0${i+1}</span><h3>${s[0]}</h3><div><p>${s[1]}</p><div class="chips">${s[2].map(c=>`<span class="chip">${c}</span>`).join('')}</div></div></article>`).join('')}</div>`;
const cta=(t='Tell us your challenge.')=>`<section class="section"><div class="wrap cta"><div><span class="kicker">LET'S BUILD</span><h2>${t}</h2></div><a class="btn" href="/contact/">Start a conversation →</a></div></section>`;
function home(){return `<section class="hero"><div class="wrap"><div class="eyebrow"><span>Local solution</span><span>Pan-African perspective</span><span>Global participation</span></div><h1>We help African businesses <span class="accent">secure</span> Africa’s digital future</h1><p class="hero-note">Native Insight combines an agile approach with rigorous research to reposition businesses, give investors market clarity, and evaluate impact.</p></div></section><div class="ticker"><span>DIGITAL ECONOMY ◆ DIGITAL SOCIETY ◆ DIGITAL GOVERNMENT ◆ BUSINESS TRANSFORMATION & AI ◆ RESEARCH & STRATEGY ◆ STARTUPS & SME SUPPORT ◆ DATA-DRIVEN INSIGHTS ◆ &nbsp;</span></div><section class="section"><div class="wrap"><div class="section-head"><span class="kicker">WHO WE ARE</span><div><h2>A research firm built for Africa’s competitive landscape.</h2><p class="lede">Our teams across the continent make every engagement problem-specific and sector-specific—giving clients the edge to thrive, stay ahead and win.</p></div></div><div class="stats"><div class="card stat"><strong>10+</strong><small>Years of extensive research</small></div><div class="card stat"><strong>6+</strong><small>Years delivering impactful results</small></div><div class="card stat"><strong>40+</strong><small>Consultants across Africa</small></div></div></div></section><section class="section light"><div class="wrap"><div class="section-head"><span class="kicker">WHAT WE DO</span><h2>Solutions that unlock great value.</h2></div>${serviceRows()}</div></section><section class="section"><div class="wrap"><div class="section-head"><span class="kicker">LATEST INSIGHTS</span><h2>Work with us into the future of business.</h2></div><div class="insight-grid">${data.insights.map((x,i)=>`<a class="insight reveal" href="/insights/"><img src="${A+x[1]}" alt=""><div><span class="kicker">PUBLICATIONS</span><h3>${x[0]}</h3><span>Read insight →</span></div></a>`).join('')}</div></div></section>${cta()}`}
function pageHero(k,h,p){return `<section class="page-hero"><div class="wrap"><div class="crumb">Home / ${h.replace(/<[^>]+>/g,'')}</div><span class="kicker">${k}</span><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div></section>`}
function about(){let vals=[['Objectivity','We take an objective view and maintain transparency, honesty and humility.'],['Rigour','We follow through on every commitment without shortcuts.'],['Integrity','We uphold the highest professional standards in our work and relationships.'],['Community','We carry stakeholders along and create solutions that benefit the wider community.']];return `${pageHero('WHO WE ARE','Digital development consulting for <span class="accent">Africa’s future</span>','We help African businesses grow, transform, and secure the continent’s digital future.')}<section class="section light"><div class="wrap"><div class="section-head"><span class="kicker">OUR STORY</span><div><h2>Built on evidence. Grounded in Africa.</h2><p class="lede">Native Insight leverages data analytics, machine learning, AI and evidence to solve business, social and development issues.</p></div></div><div class="feature-list">${[['Grow','Reposition businesses through research that turns complexity into advantage.'],['Transform','Modernise operating models and apply AI for measurable performance.'],['Secure','Shape policy and evaluate impact across the digital economy.']].map(x=>`<div class="feature"><span class="icon">◆</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></div></section><section class="section light"><div class="wrap"><div class="section-head"><span class="kicker">OUR CORE VALUES</span><h2>The principles that shape our work.</h2></div><div class="values">${vals.map((x,i)=>`<div class="value"><span class="kicker">0${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}</div></div></section><section class="section"><div class="wrap"><div class="section-head"><span class="kicker">THE JOURNEY</span><h2>A track record across Africa.</h2></div><div class="timeline">${[['2020','Founded in Lagos'],['2022','Pan-African network'],['2023','Academy & convenings'],['2026','Transformation & AI']].map(x=>`<div class="time"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div></div></section>${cta()}`}
function services(){return `${pageHero('OUR PRACTICE','We help African businesses <span class="accent">grow, transform and secure</span> Africa’s digital future','Problem-specific. Sector-specific. Pan-African.')}<section class="section light"><div class="wrap">${serviceRows()}</div></section><section class="section"><div class="wrap"><div class="section-head"><span class="kicker">HOW WE WORK</span><h2>An agile method, built around your problem.</h2></div><div class="timeline">${[['01','Frame'],['02','Research'],['03','Synthesise'],['04','Activate']].map(x=>`<div class="time"><strong>${x[0]}</strong><h3>${x[1]}</h3></div>`).join('')}</div></div></section>${cta('Talk to us.')}`}
function team(){return `${pageHero('THE PEOPLE BEHIND THE INSIGHT','Our team and <span class="accent">network</span>','Agile consultants across Africa, Europe and North America, plus 40+ field researchers mobilised across 20 markets.')}<section class="section"><div class="wrap"><div class="section-head"><span class="kicker">LEADERSHIP</span><h2>The minds steering the research.</h2></div><div class="team">${data.team.map(x=>`<article class="person reveal"><img src="${A+x[2]}" alt="${x[0]}"><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>${cta('Reach out to us.')}`}
function insights(reports=false){let extra=[['The current political situation in Guinea','field-1.jpeg'],['What the eligible customer scheme means for electricity prices in Nigeria','field-2.jpeg'],['Africa’s digital economy outlook 2025','field-3.jpeg']];let items=reports?[['Digital inclusion and ecosystem development','hero-stage.jpeg'],['Connectivity gaps and investment opportunities','field-2.jpeg'],['Africa’s digital economy outlook 2025','field-3.jpeg']]:data.insights.concat(extra);return `${pageHero(reports?'REPORT ARCHIVE':'OUR THINKING',reports?'Our <span class="accent">Reports</span>':'Africa’s <span class="accent">digital economy</span>',reports?'We synthesise complex market information to demystify sectors for investors and stakeholders.':'We break down markets, events and numbers to keep you informed on trends, investment and opportunities.')}<section class="section light"><div class="wrap"><div class="archive">${items.map(x=>`<article class="reveal"><img src="${A+x[1]}" alt=""><div class="copy"><span class="kicker">${reports?'PDF · REPORT':'PUBLICATIONS'}</span><h3>${x[0]}</h3><a href="#">Read ${reports?'report':'article'} →</a></div></article>`).join('')}</div></div></section>${cta()}`}
function careers(){return `${pageHero('JOIN THE TEAM','Join our <span class="accent">team</span>','We’re building the future of African digital economy insights and need sharp minds to help us get there.')}<section class="section light"><div class="wrap"><div class="section-head"><span class="kicker">WHY NATIVE INSIGHT</span><h2>More than a job.</h2></div><div class="feature-list">${[['Real impact','Shape decisions in boardrooms and ministries.'],['Pan-African reach','Work across 20 markets with colleagues on the ground.'],['Learning & growth','Mentorship and exposure that accelerate your career.']].map(x=>`<div class="feature"><span class="icon">◉</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></div></section><section class="section"><div class="wrap"><div class="section-head"><span class="kicker">WHERE YOU FIT</span><h2>Roles we hire for.</h2></div>${[['Interns','3–6 months · Project-based'],['Analysts','Full-time · Pan-African'],['Consultants','Full-time or project-based']].map((x,i)=>`<div class="service"><span class="num">0${i+1}</span><h3>${x[0]}</h3><div><p>${x[1]}</p><a href="#apply">Apply →</a></div></div>`).join('')}</div></section>${form('Submit application',true)}`}
function form(button='Send message',career=false){return `<section id="apply" class="section light"><div class="wrap"><div class="section-head"><span class="kicker">${career?'APPLY NOW':'TELL US YOUR CHALLENGE'}</span><h2>${career?'One form, every track.':'Send us a message.'}</h2></div><form class="form"><label>${career?'FIRST NAME':'YOUR NAME'}<input required></label>${career?'<label>LAST NAME<input required></label>':''}<label>EMAIL<input type="email" required></label><label>SUBJECT<select><option>Research & Strategy Advisory</option><option>Business Transformation & AI</option><option>Data-driven Insights</option><option>Careers</option></select></label><label class="wide">${career?'WHY NATIVE INSIGHT?':'YOUR MESSAGE'}<textarea required></textarea></label><div class="wide"><button class="btn" type="submit">${button} →</button><p class="form-note"></p></div></form></div></section>`}
function contact(){return `${pageHero('TELL US YOUR CHALLENGE','Let’s build something <span class="accent">valuable</span>.','Tell us what you are working on and where you need clarity.')} ${form()}<section class="section"><div class="wrap grid2"><div class="card"><span class="kicker">CALL</span><h2>+234 904 800 6929</h2></div><div class="card"><span class="kicker">EMAIL</span><h2>consult@nativeinsights.com</h2></div></div></section>`}
function events(){let es=[['14 OCT','The Africa Digital Leap Summit','Eko Convention Centre · Lagos'],['09 SEP','Roundtable: AI for African Enterprise','Nairobi, Kenya'],['22 JUL','Digital Economy Policy Briefing','Virtual · Pan-African'],['30 MAY','Startups & SME Investment Forum','Accra, Ghana']];return `${pageHero('PARTNERSHIPS & CONVENINGS','Where findings become <span class="accent">policy</span>.','Topical conferences and network events where key findings and policy innovations are debated.')}<section class="section light"><div class="wrap"><div class="section-head"><span class="kicker">UPCOMING & RECENT</span><h2>The calendar.</h2></div><div class="events">${es.map(x=>`<div class="event"><strong>${x[0]}</strong><div><h3>${x[1]}</h3><p>${x[2]}</p></div><span class="chip">OPEN</span></div>`).join('')}</div></div></section>`}
function academy(){return `${pageHero('NI ACADEMY','Building Africa’s <span class="accent">next minds</span>.','Critical skills, ethics and mentorship for young minds—combining expert-led training with real-world application.')}<section class="section light"><div class="wrap"><div class="section-head"><span class="kicker">PROGRAMMES</span><h2>What you can learn.</h2></div><div class="feature-list">${[['Research & Data Fundamentals','8-week cohort · Live, expert-led'],['Strategy & Advisory','10-week cohort · Case-based'],['Applied AI for Business','12-week cohort · Hands-on labs']].map(x=>`<div class="feature"><span class="kicker">PROGRAMME</span><h3>${x[0]}</h3><p>${x[1]}</p><a href="/contact/">Details →</a></div>`).join('')}</div></div></section><section class="section"><div class="wrap stats">${[['1,200+','Professionals trained'],['30+','Expert mentors'],['92%','Report career advancement']].map(x=>`<div class="card stat"><strong>${x[0]}</strong><small>${x[1]}</small></div>`).join('')}</div></section>`}
function media(){return `${pageHero('NEWSROOM','In the <span class="accent">spotlight</span>','Market activities, events and the numbers keeping Africa informed.')}<section class="section light"><div class="wrap"><div class="section-head"><span class="kicker">PRESS & COVERAGE</span><h2>Ideas travelling beyond the room.</h2></div><div class="grid2"><div class="feature"><span class="kicker">UPGRADE TV</span><h3>Reviewing the Hike in Business Subscriptions</h3><p>DStv, telecoms and the changing cost of participation.</p></div><div class="feature"><span class="kicker">PLUS TV AFRICA</span><h3>Africa’s Tech Ecosystem</h3><p>Positioning the continent for sustainable growth.</p></div></div></div></section>${cta('Press enquiries?')}`}
let path=location.pathname.replace(/\/+$/,'')||'/';let view=path==='/'?home():path==='/about'?about():path==='/what-we-do'?services():path==='/our-team'?team():path==='/insights'?insights():path==='/reports'?insights(true):path==='/careers'?careers():path==='/contact'?contact():path==='/ni-events'?events():path==='/academy'?academy():path==='/media'?media():home();document.getElementById('app').innerHTML=header()+`<main>${view}</main>`+footer();document.querySelector('.menu').onclick=()=>document.querySelector('.mobile-panel').classList.toggle('open');document.querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();f.querySelector('.form-note').textContent='Thanks — this demo form is ready to connect to your preferred form service.'});let io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('in')),{threshold:.12});document.querySelectorAll('.reveal').forEach(x=>io.observe(x));
